// Gerado por `npm run docs`. Não edite à mão — o texto vem dos comentários @tech.
export const techDetails: Record<string, { file: string; line: number; detail: string }> = {
  "WebGL2 puro (sem biblioteca)": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 7, detail: "Em ~100 linhas de JS: compila vertex + fragment shader, linka o programa, pega as localizações dos uniforms e desenha UM triângulo por frame. Nada de Three.js, buffers ou atributos." },
  "Triângulo full-screen via gl_VertexID": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 22, detail: "Truque clássico: em vez de um quad (2 triângulos + buffer), um ÚNICO triângulo maior que a tela. `gl_VertexID` vale 0,1,2 → (x,y) = (0,0), (2,0), (0,2) após `(id<<1)&2` e `id&2`; ×2−1 leva a (-1,-1),(3,-1),(-1,3). A parte visível [-1,1]² é coberta inteira e não há diagonal (sem desperdício). `drawArrays(TRIANGLES,0,3)` não precisa de nenhum buffer nem atributo." },
  "Domain warping com FBM": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 33, detail: "FBM = soma de várias oitavas de ruído (cada uma com metade da amplitude e frequência girada/maior). \"Domain warping\" = usar o FBM para DEFORMAR as coordenadas do próprio FBM: q = fbm(p), r = fbm(p + 4q), f = fbm(p + 4r). As dobras de fluido orgânico nascem dessa composição. As cores (c0..c3) são misturadas por `smoothstep` sobre f, |q| e |r|. Custo: ~15 chamadas de fbm por pixel — por isso a resolução é dinâmica." },
  "Lente que segue o mouse": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 69, detail: "lente: o espaço \"estufa\" perto do cursor, mais forte quanto mais rápido o mouse" },
  "Resolução dinâmica": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 213, detail: "resolução dinâmica: a cada 30 frames avalia o custo médio. Frame médio > 22 ms → reduz a escala do canvas em 15%; < 15 ms → sobe 6% (até 1,5× ou o DPR). O CSS estica o canvas para a tela, então o usuário só percebe um pouco menos de nitidez — nunca engasgos." },
  "Pausa inteligente do render loop": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 232, detail: "O loop só roda se o canvas está VISÍVEL (IntersectionObserver) E a aba está ativa (`document.hidden`). `start`/`stop` são idempotentes e `sync` decide; com `prefers-reduced-motion` desenha um único quadro." },
  "Canvas criado no efeito (StrictMode-safe)": { file: "src/pages/lumen/ShaderCanvas.tsx", line: 115, detail: "O <canvas> é criado aqui (e não no JSX) porque o StrictMode monta/desmonta/monta o efeito: reaproveitar o mesmo elemento devolveria um contexto WebGL já \"perdido\" por loseContext(). Cada montagem cria um canvas NOVO e o cleanup o remove — nenhum contexto fica órfão." },
  "GSAP SplitText com máscara por caractere": { file: "src/pages/lumen/Lumen.tsx", line: 65, detail: "`SplitText.create(el, { type: 'chars', mask: 'chars' })` envolve CADA letra num span com `overflow: clip`; animar `yPercent: 115` faz a letra subir \"de dentro de um buraco\" em vez de só aparecer. `aria: 'auto'` mantém o texto acessível a leitores de tela. O stagger de 0,06 s cria a onda. Letras sobem de dentro de uma máscara (overflow: clip) com leve rotação" },
  "Blur reveal por palavra": { file: "src/pages/lumen/Lumen.tsx", line: 74, detail: "Mesma ideia, `type: 'words'`: cada palavra entra de opacity 0 / y 18 / `filter: blur(10px)` para nítida, com stagger curto (0,045 s) — o texto \"entra em foco\" como uma lente ajustando. Subtítulo palavra-a-palavra com blur" },
  "Parallax do hero com useScroll/useTransform": { file: "src/pages/lumen/Lumen.tsx", line: 50, detail: "`useScroll({ target, offset })` devolve o progresso 0→1 do scroll DENTRO da seção (do topo dela até ela sair da tela). `useTransform` mapeia esse número em valores de estilo: o título desce 28%, o shader dá zoom de 1→1,25× e o conteúdo some. Tudo são MotionValues → o Motion escreve no DOM sem re-render." },
  "Marquee guiada pela velocidade do scroll": { file: "src/pages/lumen/Lumen.tsx", line: 147, detail: "Cadeia de MotionValues: scrollY → useVelocity (px/s) → useSpring (suaviza) → `factor` (acelera/inverte) e `skew` (inclina até ±9°). A cada frame (`useAnimationFrame`) o deslocamento base é somado ao impulso do scroll; rolar para cima inverte o sentido. O conteúdo é DUPLICADO e `wrap(-50, 0, v)` volta ao início ao chegar a 50% — loop perfeito sem \"pulo\"." },
  "Contadores animados em viewport": { file: "src/pages/lumen/Lumen.tsx", line: 195, detail: "`useInView(ref, { once: true })` dispara quando o número entra na tela (20% antes da borda). Aí `animate(0, to)` do Motion interpola e, em `onUpdate`, escreve `textContent` DIRETO no nó — 60 atualizações/s sem nenhum re-render. O cleanup chama `controls.stop()` (seguro com StrictMode)." },
  "Botão magnético": { file: "src/components/Magnetic.tsx", line: 8, detail: "Como funciona, em 3 camadas: 1. `pointermove` mede a distância do cursor ao CENTRO do wrapper e grava em MotionValues (`mx`, `my`) multiplicada por `strength` (0,35 = o botão anda 35% do caminho até o cursor) 2. `useSpring` transforma esse alvo em movimento com física (mola) — dá o \"puxão\" elástico e o retorno quando o cursor sai (`onPointerLeave` zera o alvo) 3. `useTransform(x, v => v * 0.45)` desloca o CONTEÚDO interno 45% a mais que o wrapper: parallax interno MotionValues não causam re-render: o Motion escreve direto no `transform` (compositor). Uso: <Magnetic strength={0.4}><button>Clique</button></Magnetic>" },
  "Cards com tilt 3D + spotlight": { file: "src/pages/lumen/Lumen.tsx", line: 246, detail: "Duas camadas independentes: (1) TILT — o ponteiro vira x,y em [0,1] (MotionValues → springs) e `useTransform` converte em rotateX/rotateY de ±7°/±9° com `transformPerspective`; (2) SPOTLIGHT — o mesmo ponteiro grava as custom properties `--mx/--my` no elemento e o CSS (lumen.css `a::before`) desenha um `radial-gradient` ali. A cor do card vem de UMA variável `--accent` (page.accent); o resto é `color-mix()` no CSS." },
  "Cards empilhados com sticky": { file: "src/pages/lumen/Lumen.tsx", line: 362, detail: "Cada card fica dentro de um wrapper `position: sticky` com `top` crescente (14vh + 28px·i), então os cards \"grudam\" um pouco abaixo do anterior formando uma pilha. `useScroll({ target: box })` dá o progresso do bloco todo; em StackCard, `useTransform` encolhe o card (scale) e escurece (`dim`) conforme os seguintes chegam por cima." },
  "mix-blend-mode: difference no título": { file: "src/pages/lumen/lumen.css", line: 147, detail: "`mix-blend-mode: difference` subtrai a cor do título (branco) da do que está ATRÁS (o shader): sobre áreas escuras o texto fica claro; sobre áreas claras ele INVERTE para escuro. Contraste garantido sem calcular nada. `font-stretch: 78%` usa o eixo de largura da Bricolage Grotesque (fonte variável)." },
  "Bento grid + color-mix()": { file: "src/pages/lumen/lumen.css", line: 327, detail: "Grade de 6 colunas; cada card ocupa 2, 3 ou 4 colunas (`.lumen-span-*`) — o desenho \"bento\". `minmax(0,1fr)` impede que conteúdo largo estoure a coluna. Cada card recebe UMA cor (`--accent`, vinda de pages.ts) e todas as demais (fundo, borda, tags, brilho) são derivadas com `color-mix(in oklab, var(--accent) X%, …)`: trocar a cor de uma página muda o card inteiro de forma coerente." },
  "Texto com gradiente e contorno": { file: "src/pages/lumen/lumen.css", line: 238, detail: "Dois truques de tipografia só em CSS: no marquee, `-webkit-text-stroke` desenha só o CONTORNO das letras (as palavras pares ficam vazadas, as ímpares cheias); nos números (.lumen-numbers strong) um gradiente de fundo + `background-clip: text` + `color: transparent` \"pinta\" as letras com o gradiente." },
  "CSS nesting nativo": { file: "src/pages/lumen/lumen.css", line: 7, detail: "Seletores aninhados com `&` (ex.: `.lumen { & em { … } }`, `.lumen-btn { &:hover { … } }`) direto no CSS, sem Sass/PostCSS. O Vite 8 (lightningcss) deixa o aninhamento como está nos navegadores que o suportam." },
  "@property (propriedades tipadas)": { file: "src/pages/prisma/prisma.css", line: 20, detail: "Variável CSS comum é só texto: não dá para animá-la (o navegador não sabe interpolar \"0deg\" → \"360deg\"). `@property --angle { syntax: '<angle>' }` registra o TIPO; aí `@keyframes { to { --angle: 360deg } }` anima de verdade — é o que faz o gradiente cônico GIRAR (borda dos cartões), o matiz DERIVAR (--shift) e o contador do anel contar (--p, inteiro). `inherits: true` deixa os filhos enxergarem o valor animado." },
  "Cor relativa em OKLCH": { file: "src/pages/prisma/prisma.css", line: 82, detail: "`oklch(from var(--c1) l c calc(h + 70))` lê as coordenadas L, C, H de --c1 e devolve uma cor NOVA com o matiz deslocado em 70°. Resultado: uma paleta de 3 cores harmônicas derivada de UM matiz base — mexer em `--hue` recalcula tudo. OKLCH é perceptualmente uniforme (mesma luminosidade = mesmo \"brilho\" percebido). Cores derivadas com \"relative color syntax\": mudam todas quando --hue muda" },
  "Interpolação de gradiente em OKLCH": { file: "src/pages/prisma/prisma.css", line: 146, detail: "`in oklch longer hue` pede ao navegador para interpolar no espaço OKLCH pelo caminho LONGO do matiz: o gradiente passa por várias cores vivas, sem o cinza \"lamacento\" que o interpolador sRGB padrão cria no meio." },
  "light-dark() + color-scheme": { file: "src/pages/prisma/prisma.css", line: 70, detail: "`color-scheme: light` (e `dark` no [data-theme='dark']) diz ao navegador qual esquema vale; `light-dark(A, B)` devolve A no claro e B no escuro — UM token por cor, sem duplicar blocos em @media (prefers-color-scheme). As cores usam OKLCH com o matiz `--hue`, então o tema inteiro \"gira\" de cor ao mexer no slider." },
  "Troca de tema com View Transition circular": { file: "src/pages/prisma/Prisma.tsx", line: 46, detail: "`document.startViewTransition(callback)` tira um print do estado atual, executa o callback (que muda o DOM) e anima do print velho para o novo. `flushSync` obriga o React a aplicar o novo tema SINCRONAMENTE dentro do callback — sem isso o navegador capturaria o \"depois\" antes do React renderizar. O círculo nasce no clique porque gravamos --vt-x/--vt-y (mesmas variáveis da transição entre páginas, ver index.css). Fallback: se a API não existir (ou houver reduced-motion), aplica direto." },
  "Scroll-driven: barra de progresso": { file: "src/pages/prisma/prisma.css", line: 137, detail: "`animation-timeline: scroll(root)` troca o relógio da animação: em vez de TEMPO, o progresso é a posição do scroll da página (0% no topo → 100% no fim). A barra cresce com `scale: 0 → 1`, tudo no compositor — sem listener de scroll, sem requestAnimationFrame, sem JS." },
  "Scroll-driven: reveals com view()": { file: "src/pages/prisma/prisma.css", line: 552, detail: "`animation-timeline: view()` liga a animação à VISIBILIDADE do próprio elemento: 0% quando ele começa a entrar na viewport, 100% quando sai. `animation-range: entry 0% cover 46%` deixa cada efeito (subida, pop, wipe, blur, flip) visível durante a rolagem e o encerra com o cartão ainda inteiro na tela. A keyframe é escolhida por `animation: var(--fx)` — o JSX grava `--fx: prisma-rise|pop|wipe|blur|flip` em cada cartão, então UMA regra produz 5 entradas diferentes." },
  "Parallax por scroll em CSS puro": { file: "src/pages/prisma/prisma.css", line: 443, detail: "Os 3 cartões do hero compartilham uma animação `prisma-parallax` ligada a `scroll(root)` e limitada a `animation-range: 0 100vh` (só o primeiro viewport). A distância final vem de `--rise` (160, 300, 90 px, definido inline no JSX): mesmo keyframe, velocidades diferentes." },
  "view-timeline nomeada": { file: "src/pages/prisma/prisma.css", line: 1245, detail: "`view-timeline: --story` cria uma timeline NOMEADA a partir da visibilidade desta seção e a expõe aos descendentes (`timeline-scope`/herança); cubo, anel e legendas usam `animation-timeline: --story` e andam sincronizados por UMA única linha do tempo." },
  "Cena 3D só com CSS": { file: "src/pages/prisma/prisma.css", line: 1133, detail: "O cubo é um contêiner com `transform-style: preserve-3d` (os filhos mantêm a profundidade) e `perspective` no pai. Cada face `.f1…f6` é um quadrado girado em um eixo (rotateY/rotateX) e empurrado `translateZ(metade da aresta)`. O \"vidro\" vem de `backdrop-filter`. Nenhum canvas, nenhum WebGL." },
  "Contador CSS animado por @property": { file: "src/pages/prisma/prisma.css", line: 1183, detail: "`--p` é um <integer> registrado e animado de 0 a 100 pela timeline do scroll. `counter-reset: pct var(--p)` copia esse número para um contador CSS e `content: counter(pct) '%'` o imprime — o \"57%\" do anel é TEXTO GERADO POR CSS. O mesmo `--p` alimenta o `conic-gradient` do anel." },
  "Borda cônica rotativa": { file: "src/pages/prisma/prisma.css", line: 494, detail: "O pseudo-elemento `::before` cobre o cartão com um `conic-gradient(from var(--angle) …)`; `--angle` é a @property animada (`prisma-spin`). A máscara usa duas camadas (`content-box` e a caixa inteira) combinadas com `mask-composite: exclude`: sobra só o ANEL de 1,5px (padding) — o miolo vira transparente." },
  "Motion path em CSS": { file: "src/pages/prisma/prisma.css", line: 372, detail: "Cada blob (`i`) percorre uma curva de Bézier definida em `offset-path: path('M … C …')`; a animação só mexe em `offset-distance: 0 → 100%` (`prisma-orbit`). `animation-delay: var(--d)` (negativo, vindo do JSX) espalha os 4 blobs pelo mesmo caminho. O `filter: url(#prisma-goo)` do container funde os círculos que se tocam." },
  "Filtros SVG: gooey e turbulência": { file: "src/pages/prisma/Prisma.tsx", line: 67, detail: "Um <svg> invisível guarda dois filtros que o CSS referencia com `filter: url(#id)`: • prisma-goo: borra os blobs (feGaussianBlur) e depois ENDURECE o alfa com feColorMatrix (×24 −10): onde dois círculos se sobrepõem a borda \"gruda\" como gota de óleo. • prisma-liquid: feTurbulence (ruído fractal, animado por <animate>) alimenta feDisplacementMap, que empurra os pixels do título — o texto \"ondula\" no hover. Filtros SVG rodam na GPU em navegadores modernos e funcionam em QUALQUER elemento HTML." },
  "Container queries + cqi": { file: "src/pages/prisma/prisma.css", line: 689, detail: "`.cq` é um contêiner (`container: card / inline-size`) e o `.cq-card` dentro dele muda de layout conforme a LARGURA DO CONTÊINER, não da janela: `@container card (min-width: 480px)` → cartão com arte ao lado; `(min-width: 700px)` → painel em colunas. A tipografia usa `cqi` (1% da largura do contêiner) e a caixa é redimensionável por `resize: horizontal` para você ver a mágica ao vivo." },
  "scroll-state container query": { file: "src/pages/prisma/prisma.css", line: 173, detail: "`container-type: scroll-state` torna o header um contêiner que \"conhece\" o estado de rolagem dele. Em `.prisma-head__bar`, `@container scroll-state(stuck: top)` aplica vidro/sombra SÓ enquanto o header está grudado no topo (position: sticky). Antes isso exigia IntersectionObserver + classe via JS." },
  ":has() como lógica de UI": { file: "src/pages/prisma/prisma.css", line: 717, detail: "`:has()` é o \"seletor de pai\": `.has-lab:has(#p2:checked)` troca o matiz do laboratório INTEIRO quando o rádio do plano 2 está marcado; `.dimgrid:has(.tile:hover) .tile:not(:hover)` apaga os irmãos do tile sob o mouse; `.prisma:has(#drift:checked)` liga a animação de deriva de cor da página toda via um checkbox do header. Três comportamentos que antes exigiam estado em JavaScript." },
  "Transição de @property (morph de matiz)": { file: "src/pages/prisma/prisma.css", line: 728, detail: "Como `--hue` foi registrada com `@property` (tipo <number>), `transition: --hue .9s` INTERPOLA o número: ao trocar de plano, todas as cores derivadas (que dependem de --hue) deslizam suavemente em vez de pular." },
  ":user-invalid / :user-valid": { file: "src/pages/prisma/prisma.css", line: 911, detail: "`:invalid` já nasce ativo (campo vazio obrigatório fica vermelho antes de o usuário digitar). `:user-invalid` só vale DEPOIS da interação (blur/submit). Combinado com `:has()` mostramos a mensagem de erro/sucesso sem JavaScript de validação. :user-invalid só dispara depois que o usuário interage" },
  "field-sizing: content": { file: "src/pages/prisma/prisma.css", line: 895, detail: "`field-sizing: content` faz o <textarea>/<input> dimensionar-se pelo CONTEÚDO digitado: o campo cresce linha a linha sozinho (antes: um listener `input` recalculando `scrollHeight`)." },
  "Anchor positioning": { file: "src/pages/prisma/prisma.css", line: 1024, detail: "O botão declara `anchor-name: --chip-a` e o popover `position-anchor: --chip-a` (ambos inline no JSX). Com `position-area: top` o navegador posiciona o popover ACIMA do botão — sem calcular coordenadas em JS nem Popper/Floating UI. `position-try-fallbacks: flip-block` inverte para baixo se faltar espaço no topo. ancorado ao botão correspondente (position-anchor vem inline)" },
  "Popover API + @starting-style": { file: "src/pages/prisma/prisma.css", line: 992, detail: "O atributo HTML `popover` (+ `popovertarget` no botão) joga o elemento na TOP LAYER: sem z-index, sem portal, fecha com Esc/clique fora, foco gerenciado. Para animar, `&:popover-open` define o estado final e `@starting-style` o inicial da ENTRADA; `display`/`overlay` com `allow-discrete` mantêm o elemento visível durante a SAÍDA. transição de entrada/saída de elementos da top layer" },
  "details exclusivo + interpolate-size": { file: "src/pages/prisma/prisma.css", line: 1093, detail: "`<details name=\"faq\">`: todos com o mesmo `name` formam um acordeão EXCLUSIVO (abrir um fecha os outros) — zero JS. Para animar a altura de 0 a `auto`, `interpolate-size: allow-keywords` (no .prisma) libera a transição para `auto` e `::details-content` é o pseudo-elemento que contém o miolo." },
  "Carrossel CSS nativo": { file: "src/pages/prisma/prisma.css", line: 1353, detail: "Base: `overflow-x: auto` + `scroll-snap-type: x mandatory`. Chrome 135+ gera, só com CSS, os marcadores (`scroll-marker-group` + `li::scroll-marker`, com `:target-current` para o ativo) e as setas (`::scroll-button(left|right)` com `content`). Sem suporte, continua um scroll-snap utilizável. Carrossel nativo (Chrome 135+): marcadores e botões gerados pelo CSS" },
  "view(inline) em slides": { file: "src/pages/prisma/prisma.css", line: 1444, detail: "`view(inline)` mede a posição de CADA slide no eixo horizontal do scroller: ao se aproximar do centro o slide ganha escala/opacidade (keyframes `prisma-slide`), criando o foco no item atual sem JS." },
  "@layer + escopo por classe": { file: "src/pages/prisma/prisma.css", line: 11, detail: "`@layer prisma { … }` põe TODAS as regras numa camada: camadas declaradas depois vencem as anteriores independentemente da especificidade, então estas regras não brigam com o reset do Tailwind (camada `base`). Além disso tudo está aninhado sob `.prisma`, impedindo vazamento para as outras páginas do SPA." },
  "Progressive enhancement com @supports": { file: "src/pages/prisma/prisma.css", line: 153, detail: "Estilos que dependem de `animation-timeline` ficam dentro de `@supports (animation-timeline: …)`. Quem não tem suporte vê a barra em `scale: 0` (invisível) e os cartões já no estado final: nada quebra, só perde o efeito." },
  "text-wrap: balance / pretty": { file: "src/pages/prisma/prisma.css", line: 112, detail: "`balance` equilibra o comprimento das linhas de títulos (sem \"uma palavra sozinha\" na última); `pretty` evita viúvas/órfãs em parágrafos. Ambos só mudam a quebra de linha — zero custo de JS." },
  "Fonte variável reativa ao cursor": { file: "src/pages/tipo/Tipo.tsx", line: 38, detail: "Cada letra é um <span data-ch>. A cada frame (gsap.ticker) medimos a distância do CENTRO de cada letra até o ponteiro, convertemos em t ∈ [0,1] (1 = em cima do cursor; raio = 42% da largura da palavra) e suavizamos com smoothstep (t²(3−2t)). Esse valor \"e\" mapeia 4 EIXOS da Fraunces escritos em `font-variation-settings`: wght 120→900, opsz 9→144 (tamanho óptico), SOFT 0→100 (arredondamento) e WONK 0/1 (formas alternativas). Uma única fonte variável = infinitos pesos sem baixar arquivos extras. `aria-label` no <h1> + `aria-hidden` nas letras mantêm o texto legível para leitores de tela." },
  "Ponteiro virtual em telas de toque": { file: "src/pages/tipo/Tipo.tsx", line: 59, detail: "Sem movimento de ponteiro nos últimos 2,5 s (ou sem mouse, como no celular) o \"cursor\" passa a ser uma senoide que varre a largura da palavra: `box.left + (sin(t·0,7)·0,5 + 0,5)·box.width`. sem ponteiro recente → varredura automática" },
  "Loops no gsap.ticker": { file: "src/pages/tipo/Tipo.tsx", line: 74, detail: "Efeitos contínuos (proximidade das letras, lente do cartaz, impulso do marquee) assinam o MESMO ticker do GSAP em vez de abrir um requestAnimationFrame cada: um relógio só, ordem previsível, e `ticker.remove` no cleanup garante que nada continue rodando depois de sair da página." },
  "ScrollTrigger scrub (barra de leitura)": { file: "src/pages/tipo/Tipo.tsx", line: 142, detail: "`scrub: 0.3` liga o progresso do tween ao do scroll (com 0,3 s de suavização): a barra `.tipo-progress` vai de scaleX 0 a 1 conforme a página inteira é lida (trigger = raiz, de 'top top' a 'bottom bottom'). 2. Barra de leitura" },
  "SplitText por linhas com máscara + autoSplit": { file: "src/pages/tipo/Tipo.tsx", line: 152, detail: "`type: 'lines', mask: 'lines'` divide o título em LINHAS (as quebras reais, depois do layout) e põe cada uma numa máscara; `autoSplit: true` refaz o split sozinho quando a janela muda de tamanho ou a fonte termina de carregar (senão as linhas ficariam erradas). A animação mora em `onSplit` para ser recriada a cada re-split. 3. Títulos: linhas sobem de dentro de máscaras. autoSplit refaz o split em resize/fontes" },
  "Texto que acende com o scroll": { file: "src/pages/tipo/Tipo.tsx", line: 173, detail: "SplitText por PALAVRAS + `fromTo(opacity .12 → 1)` com `stagger` e `scrub: true`: o stagger distribui as palavras ao longo do trecho de scroll (de 'top 70%' a 'bottom 55%'), então o parágrafo \"acende\" na velocidade em que você lê/rola — e apaga se você rolar de volta. 4. Manifesto: palavras acendem conforme o scroll (scrub)" },
  "Marca-texto animado": { file: "src/pages/tipo/Tipo.tsx", line: 189, detail: "Cada <mark> ganha um ScrollTrigger só para alternar a classe `is-on` (`onToggle`); o CSS (tipo.css `mark.is-on`) transiciona `background-size` de 0 a 100%, simulando um marca-texto passando sobre a palavra." },
  "Scroll horizontal “pinado”": { file: "src/pages/tipo/Tipo.tsx", line: 196, detail: "`pin: true` congela a seção na tela enquanto o scroll vertical continua; `scrub: 0.7` liga o progresso do scroll ao tween `x: -dist()` da faixa de cartões (que desliza para a esquerda). `end: () => '+=' + dist()` faz o trecho de scroll ter EXATAMENTE a largura a percorrer; `invalidateOnRefresh` recalcula `dist()` ao redimensionar; `anticipatePin` evita o \"tranco\" na hora de grudar. O contador \"01 / 05\" sai de `onUpdate`. 5. Scroll horizontal \"pinado\" + parallax interno via containerAnimation" },
  "containerAnimation (parallax interno)": { file: "src/pages/tipo/Tipo.tsx", line: 225, detail: "Dentro de uma animação HORIZONTAL o \"scroll\" do trigger não é o da página: `containerAnimation: slide` diz ao ScrollTrigger para medir `start: 'left right'` → `end: 'right left'` em relação ao movimento do tween `slide`. Assim cada glifo gigante desliza (±18%) e gira (±7°) numa velocidade própria enquanto o cartão atravessa a tela — parallax interno ao carrossel." },
  "gsap.matchMedia": { file: "src/pages/tipo/Tipo.tsx", line: 202, detail: "`gsap.matchMedia().add('(min-width: 900px)', fn)` só cria a coreografia pinada em telas largas e a REVERTE automaticamente quando a condição deixa de valer; no mobile a seção vira uma lista vertical normal (CSS)." },
  "DrawSVGPlugin": { file: "src/pages/tipo/Tipo.tsx", line: 249, detail: "`drawSVG: '0%' → '100%'` anima `stroke-dasharray/offset` do <path> até o traço se \"desenhar\" sozinho. Ligado ao scroll pelo MESMO objeto `swashTrigger` da caneta (abaixo): os dois andam sincronizados." },
  "MotionPathPlugin": { file: "src/pages/tipo/Tipo.tsx", line: 253, detail: "`motionPath: { path: swash, align: swash, autoRotate: true }` leva o elemento `.tipo-pen` ao longo da curva do SVG, alinhado a ela e girando para acompanhar a tangente: a \"caneta\" parece escrever o traço." },
  "GSAP Flip": { file: "src/pages/tipo/Tipo.tsx", line: 294, detail: "FLIP = First, Last, Invert, Play. (1) `Flip.getState('.tipo-item')` fotografa posição/tamanho ANTES; (2) `change()` muda o estado do React (grade↔lista ou filtro) e `flushSync` força o DOM a refletir isso AGORA; (3) `Flip.from` compara com a foto, aplica a transformação inversa e anima até a posição nova. Resultado: os MESMOS elementos deslizam para o novo layout (sem remontar). `absolute: true` evita saltos de layout durante a animação; `onEnter/onLeave` animam itens que aparecem/somem por causa do filtro." },
  "Lente com clip-path": { file: "src/pages/tipo/Tipo.tsx", line: 314, detail: "O cartaz tem DUAS camadas de texto empilhadas (uma preta, outra laranja); a de cima só aparece dentro de `clip-path: circle(var(--r) at var(--x) var(--y))` (tipo.css `.tipo-poster__lens`). Aqui, a cada frame do ticker, posição e raio são suavizados por lerp (0,14 / 0,12) e gravados como CSS vars — o CSS desenha o círculo. `pointerenter/leave` só mudam o raio ALVO (190px ↔ 0), então a lente \"abre\" e \"fecha\" com inércia." },
  "Marquee com impulso de velocidade": { file: "src/pages/tipo/Tipo.tsx", line: 262, detail: "O loop é um tween infinito (`xPercent: -50, repeat: -1`). `ScrollTrigger.onUpdate` lê `self.getVelocity()` e grava um \"boost\"; a cada frame o boost decai (×0,94) e `loop.timeScale(dir·(1+boost))` acelera/inverte o marquee conforme a direção do scroll — e volta suavemente à velocidade base. 7. Marquee do rodapé: velocidade reage ao scroll" },
  "Grão de papel inline": { file: "src/pages/tipo/tipo.css", line: 26, detail: "O ::before cobre a página (position: fixed) com um `background-image: url(\"data:image/svg+xml;…\")`: um SVG com `feTurbulence` (ruído fractal) + `feColorMatrix` (só canal alfa) vira textura de papel. É um data-URI — 0 requisições, 0 KB de imagem — e `mix-blend-mode: multiply` mistura o grão com as cores do papel/tinta." },
  "Texto circular com textPath": { file: "src/pages/tipo/Tipo.tsx", line: 374, detail: "O texto do selo segue o contorno de um círculo definido em <defs> (`<textPath href=\"#tipo-circle\">`). Um `rotate` contínuo (CSS, tipo.css `.tipo-badge`) o faz girar. É SVG puro: escala sem perder nitidez." },
  "Eixos tipográficos em hover": { file: "src/pages/tipo/tipo.css", line: 433, detail: "A \"capa\" de cada matéria é uma letra gigante em Fraunces. Em repouso usa SOFT 100 / WONK 1 / opsz 144; no hover (regra `.tipo-item:hover .tipo-item__cover span`) os valores de `font-variation-settings` mudam e a regra `transition: font-variation-settings .6s` INTERPOLA os eixos — a letra \"respira\" (muda de peso/suavidade) e gira -8°." },
  "gsap.context + cleanup": { file: "src/pages/tipo/Tipo.tsx", line: 135, detail: "`gsap.context(fn, scope)` registra TUDO que for criado dentro de `fn` (tweens, ScrollTriggers, SplitTexts, matchMedia). `ctx.revert()` no cleanup desfaz tudo de uma vez — o React StrictMode monta o efeito duas vezes em desenvolvimento, e sem isso cada montagem deixaria triggers duplicados. O `scope` (root) limita seletores em string ('.tipo-progress') aos descendentes desta página." },
  "use(promise) + Suspense": { file: "src/pages/pulse/Pulse.tsx", line: 127, detail: "React 19: `use` lê a Promise e SUSPENDE até o Web Worker responder. A Promise precisa ter a MESMA referência entre renders (por isso `loadDataset()` guarda em cache e Pulse usa `useMemo`): senão cada render criaria uma nova e suspenderia para sempre. O <Suspense fallback={<Skeleton/>}> (em Pulse) mostra o esqueleto." },
  "Web Worker de módulo": { file: "src/pages/pulse/dataset.ts", line: 44, detail: "`new Worker(new URL('./dataset.worker.ts', import.meta.url), { type: 'module' })` é o padrão que o Vite entende: ele empacota o worker como arquivo separado (com imports ES) e resolve a URL em dev e produção (`worker.format: 'es'` em vite.config.ts). O worker roda em outra thread: gerar 50 mil eventos não trava a UI. Termina o worker (`terminate`) assim que a resposta chega — não deixa thread ociosa." },
  "Transferable ArrayBuffers": { file: "src/pages/pulse/dataset.worker.ts", line: 72, detail: "`postMessage(msg, { transfer: [buffers] })` MOVE a posse dos ArrayBuffers para a thread principal (zero-copy, O(1)) em vez de clonar ~1,5 MB por structured clone. Depois da transferência o worker não enxerga mais esses buffers (ficam \"detached\") — por isso o worker é descartável (ver `terminate` em dataset.ts)." },
  "Dados colunares com TypedArrays": { file: "src/pages/pulse/dataset.ts", line: 10, detail: "Em vez de 50.000 objetos `{ id, ts, service, … }` (alto custo de memória e GC), guardamos UMA coluna por campo em arrays tipados compactos: Float64Array (timestamps), Uint8Array (serviço/região, índices de uma lista), Uint16Array (status), Float32Array (latência/valor). Filtros e ordenações trabalham sobre ÍNDICES (Uint32Array) e só leem as colunas necessárias — cache-friendly e rápido (ver EventsTable.tsx)." },
  "Virtualização (TanStack Virtual)": { file: "src/pages/pulse/EventsTable.tsx", line: 89, detail: "Só as linhas visíveis (+ `overscan: 14` de folga) existem no DOM — ~30 em vez de 50.000. O contêiner interno tem a ALTURA TOTAL (`virt.getTotalSize()`) para a barra de rolagem ser fiel, e cada linha é posicionada com `translateY(v.start)`. `estimateSize: 44` é a altura fixa de cada linha." },
  "useDeferredValue": { file: "src/pages/pulse/EventsTable.tsx", line: 51, detail: "`deferredQuery` fica \"atrasado\" em relação a `query`: o React atualiza o <input> NA HORA (prioridade alta) e recalcula a filtragem pesada depois, em prioridade baixa e interrompível. Digitar nunca engasga; `stale` (query !== deferredQuery) acende o contador em âmbar enquanto o resultado velho ainda é exibido." },
  "useTransition": { file: "src/pages/pulse/EventsTable.tsx", line: 58, detail: "Ordenar 50 mil linhas é caro. Envolver o `setSort` em `startSorting(() => …)` o marca como TRANSIÇÃO: o React mantém a UI responsiva (e pode abandonar o render se você clicar de novo); `sorting` (isPending) dá o feedback." },
  "Actions: form action + useActionState": { file: "src/pages/pulse/Incidents.tsx", line: 78, detail: "`useActionState(fn, estadoInicial)` devolve `[estado, action]`. `action` vai direto em `<form action={…}>`: o React monta o FormData, chama `fn(estadoAnterior, formData)` dentro de uma transição e, ao terminar, guarda o retorno em `estado` (aqui `{ error?, ok? }`). Substitui onSubmit + preventDefault + useState(loading/error)." },
  "useOptimistic": { file: "src/pages/pulse/Incidents.tsx", line: 69, detail: "`useOptimistic(valorReal, reducer)` devolve uma VERSÃO TEMPORÁRIA do estado: dentro de uma Action, chamar `addOptimistic(item)` mostra o item imediatamente; quando a Action termina, o React volta ao valor real (`items`). Se a Action falhou e não gravou nada, o item otimista simplesmente desaparece — rollback sem código. O item aparece NA HORA (otimista) e some sozinho se a ação falhar" },
  "useFormStatus": { file: "src/pages/pulse/Incidents.tsx", line: 48, detail: "Chamado num componente FILHO do <form> (aqui `Submit`), devolve `{ pending }`: true enquanto a Action roda. O botão se desabilita e mostra o spinner sem receber nenhuma prop do formulário." },
  "ref como prop (sem forwardRef)": { file: "src/pages/pulse/EventsTable.tsx", line: 24, detail: "Antes do React 19, passar `ref` a um componente de função exigia `forwardRef(...)`. Agora `ref` chega em `props` como qualquer outra; aqui ele é repassado ao <input> para o ⌘K/atalho \"/\" conseguir focar a busca." },
  "Título do documento no componente (React 19)": { file: "src/pages/pulse/Pulse.tsx", line: 248, detail: "React 19 \"eleva\" (hoist) `<title>`, `<meta>` e `<link>` renderizados em QUALQUER componente para o <head>. Cada página declara o próprio título no JSX — sem react-helmet." },
  "Zustand com selectors": { file: "src/pages/pulse/store.ts", line: 7, detail: "`create()` devolve um hook `useLive`. O estado vive FORA da árvore do React (módulo), e cada componente chama `useLive((s) => s.points)` com um SELECTOR: só re-renderiza se aquela fatia mudar (comparação por referência). Os 4 cards de métrica assinam `points` e o botão \"ao vivo\" só `live`. `tick()` cria um novo array a cada segundo (janela deslizante de WINDOW=60 pontos) — imutabilidade é o que dispara a atualização. - o \"feed ao vivo\" é simulado aqui, mas o formato é o de um WebSocket/SSE real: trocar `tick` por um `onmessage` real não exige mudar nenhum componente." },
  "Gráficos com d3-scale + d3-shape": { file: "src/pages/pulse/charts.tsx", line: 43, detail: "`scaleLinear([domínio],[imagem])` mapeia valores → pixels; `line()/area()` com `curveMonotoneX` (curva suave que não \"estoura\" entre pontos) transformam o array em string de path SVG. `useMemo` recalcula só quando `data` muda. O mesmo padrão gera o LiveChart; `pie()` + `arc()` geram o Donut." },
  "Janela deslizante com Web Animations API": { file: "src/pages/pulse/charts.tsx", line: 110, detail: "A cada segundo chega 1 ponto novo e os paths são recalculados deslocados 1 passo para a esquerda (saltaria). Para o movimento parecer CONTÍNUO, `element.animate([translateX(+passo) → translateX(0)], { duration: 1000, easing: 'linear' })` no <g> traz o gráfico de volta suavemente durante o segundo seguinte. A animação roda no compositor; o cleanup `a.cancel()` evita acúmulo; reduced-motion desliga. cada novo ponto desloca tudo 1 passo p/ esquerda; animamos de +passo → 0 para parecer contínuo" },
  "Crosshair e tooltip com Pointer Events": { file: "src/pages/pulse/charts.tsx", line: 179, detail: "Um <rect> transparente cobre a área do gráfico e captura `pointermove`. `x.invert(px)` (d3-scale) converte a posição do mouse de volta para o ÍNDICE do ponto mais próximo; com ele desenhamos a linha vertical, os dois círculos e o tooltip (limitado às bordas por `Math.min/max`)." },
  "Números animados sem re-render": { file: "src/pages/pulse/charts.tsx", line: 20, detail: "`useSpring(mv)` produz um valor que persegue `mv` com física de mola; o listener `spring.on('change')` escreve `textContent` do <span> diretamente (60×/s) — o React NÃO re-renderiza a cada frame, só quando `value` muda." },
  "Reorder (drag para priorizar)": { file: "src/pages/pulse/Incidents.tsx", line: 127, detail: "`Reorder.Group` + `Reorder.Item` (Motion) dão arrastar-e-soltar vertical com troca de lugar animada; `values`/`onReorder` mantêm a ordem no estado. `AnimatePresence` anima a SAÍDA (`exit`) de itens removidos. Itens pendentes (`dragListener={false}`) não podem ser arrastados; o botão × usa `stopPropagation` para não iniciar um arrasto." },
  "Command palette (⌘K) com dialog nativo": { file: "src/pages/pulse/CommandPalette.tsx", line: 30, detail: "Peças: (1) `score()` — busca fuzzy mínima: cada letra da busca precisa aparecer em ORDEM no rótulo; a pontuação soma as distâncias entre acertos (menor = melhor); (2) `results` — filtra e ordena os comandos com useMemo; (3) navegação por ↑/↓/Enter e `scrollIntoView({ block: 'nearest' })` mantém o item ativo visível; (4) <dialog> nativo: `showModal()` dá top layer, foco preso, Esc e ::backdrop; a animação de entrada vem de classes Tailwind `starting:` (= @starting-style). A lista de comandos é injetada por quem usa (Pulse.tsx), incluindo \"ir para página\" via `navigate(path, { viewTransition: true })`." },
  "Tailwind v4: tokens, @container e starting:": { file: "src/pages/pulse/Pulse.tsx", line: 44, detail: "- tokens: cores `bg-ink-900`, `text-mint`, `border-white/10` vêm do `@theme` em index.css (OKLCH) - `@container` na classe do cartão + variantes `@md:`/`@xl:` nos filhos (charts.tsx, EventsTable.tsx) respondem à largura DO CARTÃO, não da tela - `starting:translate-y-6 starting:opacity-0` = @starting-style: o cartão nasce deslocado/transparente e transiciona até o estado normal; `transitionDelay: i·70ms` escalona a entrada - variantes de estado: `aria-pressed:`, `aria-selected:`, `open:` estilizam a partir de atributos ARIA/HTML" },
  "Heatmap com color-mix()": { file: "src/pages/pulse/charts.tsx", line: 273, detail: "Cada célula é um <i> cuja cor é `color-mix(in oklch, mint X%, ink-800)`, com X = volume normalizado (0–100): mais eventos → mais verde. `starting:scale-50` + `transitionDelay: índice·4ms` fazem a grade \"acender\" em onda ao carregar." },
  "Donut interativo": { file: "src/pages/pulse/charts.tsx", line: 212, detail: "`pie().padAngle(0.035)` calcula ângulos de cada fatia; `arc().innerRadius(64).outerRadius(90).cornerRadius(5)` vira o path de cada uma. Cada `motion.path` anima entrada (spring escalonada) e destaque: passar o mouse numa fatia OU na legenda define `active`, que atenua as demais (opacity .28), amplia a ativa e troca o número central." },
  "Skeleton enquanto o worker trabalha": { file: "src/pages/pulse/Pulse.tsx", line: 187, detail: "Fallback do <Suspense>: blocos cinza com `animate-pulse` do Tailwind nas MESMAS posições da grade final, para o layout não \"pular\" quando os dados chegam." },
  "Motor de física (Matter.js)": { file: "src/pages/gravity/Playground.tsx", line: 41, detail: "Matter.js simula corpos rígidos 2D: gravidade, colisões, atrito, restituição (quique), restrições (molas). Física 2D com Matter.js: • Pílulas = elementos DOM (estilizados com Tailwind) cujo transform é sincronizado com os corpos a cada frame • Bolas e partículas = Canvas 2D (centenas sem custo de layout) • Arrasto próprio via Constraint + Pointer Events (não sequestra o scroll da página no mobile) • Passo fixo de 1/60s com acumulador → simulação determinística independente do monitor" },
  "Passo fixo com acumulador": { file: "src/pages/gravity/Playground.tsx", line: 296, detail: "Física instável com dt variável (monitor 144 Hz vs 60 Hz = simulações diferentes). Solução clássica: o tempo real de cada frame entra num ACUMULADOR (limitado a 100 ms para não \"espiral da morte\") e a física avança em passos FIXOS de 1/60 s (`while (acc >= STEP)`). O resultado é determinístico e idêntico em qualquer tela." },
  "DOM sincronizado com a física": { file: "src/pages/gravity/Playground.tsx", line: 327, detail: "As pílulas são <button> normais (acessíveis e estilizáveis com Tailwind) posicionados em (0,0). A cada frame o transform `translate3d(x,y) rotate(ângulo)` do CORPO do Matter é copiado para o estilo do elemento — o navegador só compõe (sem layout), então dá para ter HTML \"de verdade\" voando e girando. DOM ← física" },
  "Canvas 2D para bolas e partículas": { file: "src/pages/gravity/Playground.tsx", line: 338, detail: "Dezenas de bolas e até 400 partículas seriam centenas de elementos DOM; no canvas cada uma é só um `arc()`. A \"sombra dura\" neo-brutalista é um segundo círculo preto deslocado 4px, sem blur (barato e no estilo). Canvas ← bolas + partículas" },
  "Arrasto próprio (Constraint + Pointer Events)": { file: "src/pages/gravity/Playground.tsx", line: 184, detail: "No pointerdown, `Query.point` descobre qual corpo está sob o dedo. Em vez de teleportá-lo, criamos uma `Constraint` (mola, stiffness .16) entre o PONTO do ponteiro e aquele ponto do corpo; ao mover, só atualizamos `pointA`. A física faz o resto: o corpo é \"puxado\", bate nos outros e solta com inércia. `setPointerCapture` mantém o arrasto vivo fora do elemento. Clicar no vazio solta uma explosão de partículas." },
  "touch-action só onde precisa": { file: "src/pages/gravity/Playground.tsx", line: 446, detail: "Só as PÍLULAS têm `touch-none` (touch-action: none): arrastá-las com o dedo não rola a página. O resto do playground NÃO bloqueia o toque, então o usuário consegue rolar a página passando o dedo pelo fundo." },
  "Modos de gravidade": { file: "src/pages/gravity/Playground.tsx", line: 243, detail: "Normal/invertida mudam `engine.gravity.y` (+1/−1); zero-g zera a gravidade e dá um empurrão aleatório; ímã aplica uma FORÇA radial até o cursor a cada passo (ver loop); inclinação (celular) lê `deviceorientation` (gamma/beta)." },
  "Explosão por impulso": { file: "src/pages/gravity/Playground.tsx", line: 255, detail: "Sem forças: sobrescreve `velocity` (x ±23, y −10…−44) e `angularVelocity` de TODOS os corpos de uma vez e dispara 60 partículas. A gravidade faz o corpo voltar; o quique vem da restituição das paredes." },
  "Colisão → som + faíscas": { file: "src/pages/gravity/Playground.tsx", line: 163, detail: "`collisionStart` entrega os pares que acabaram de se tocar. A velocidade RELATIVA (|vA − vB|) mede a força do impacto: abaixo de 3,2 é ignorada (corpos repousando); acima, gera faíscas (quanto mais forte, mais partículas) e toca `hitSound(rel, id)`. Um cooldown de 90 ms por corpo evita metralhadora de sons em pilhas." },
  "Síntese com Web Audio API": { file: "src/pages/gravity/audio.ts", line: 5, detail: "Cadeia: voz → master (gain) → compressor → analyser → destino. O AnalyserNode alimenta o osciloscópio desenhado em canvas." },
  "Ruído branco como AudioBuffer": { file: "src/pages/gravity/audio.ts", line: 35, detail: "1 segundo de amostras aleatórias em [-1, 1] gravadas UMA vez num AudioBuffer mono; cada chiado (snare, hi-hat, clap) reutiliza esse buffer num BufferSource novo (barato) e o filtra: high-pass = \"chiado agudo\" (hat), band-pass = \"corpo\" de caixa/palmas." },
  "Escala pentatônica": { file: "src/pages/gravity/audio.ts", line: 52, detail: "`PENTA` = semitons [0,2,4,7,9] (sem os intervalos que \"brigam\"). A frequência é `196 · 2^(semitons/12)` (G3 como base); o índice sobe oitavas a cada 5 notas. Em hitSound o `seed` é o id do corpo físico: cada objeto sempre toca a MESMA nota, então bater em objetos diferentes forma melodias." },
  "Osciloscópio com AnalyserNode": { file: "src/pages/gravity/Gravity.tsx", line: 23, detail: "`analyser.getByteTimeDomainData(buf)` copia a forma de onda atual (1024 amostras, 0–255; 128 = silêncio) e cada amostra vira um ponto (x = índice, y = valor) de uma polilinha no canvas. Sem áudio ativo (analyser ainda não criado) desenha uma onda ociosa. Um IntersectionObserver pausa o rAF fora da tela; ResizeObserver mantém o bitmap do canvas nítido (tamanho CSS × DPR)." },
  "Pads jogáveis por toque e teclado": { file: "src/pages/gravity/Gravity.tsx", line: 93, detail: "Cada pad vem de `pads` (audio.ts) com nome, tecla e função `play`. `hit(i)` destrava o áudio (gesto do usuário), toca e acende o botão via `data-lit=\"true\"` por 120 ms — o Tailwind reage com `data-[lit=true]:` (afunda e clareia). `pointerdown` (em vez de click) reduz a latência; o listener de teclado ignora repetição de tecla (`e.repeat`), atalhos com Ctrl/Meta/Alt e digitação em campos de formulário." },
  "Drag com inércia e limites elásticos": { file: "src/pages/gravity/Gravity.tsx", line: 196, detail: "`drag` liga o arrasto (Pointer Events internos do Motion). `dragConstraints={board}` limita ao quadro; `dragElastic` deixa passar um pouco da borda e puxa de volta (borracha). `dragTransition` descreve a INÉRCIA ao soltar: `power` × velocidade define para onde o adesivo ainda desliza, `timeConstant` o quão rápido para, e `bounceStiffness/Damping` a mola de retorno ao bater no limite." },
  "z-index dinâmico": { file: "src/pages/gravity/Gravity.tsx", line: 204, detail: "`onPointerDown` incrementa um contador (`z.current`) e grava no `zIndex` do cartão tocado: o último a ser pego sempre fica por cima, como papéis numa mesa." },
  "Entrada com spring (queda)": { file: "src/pages/gravity/Gravity.tsx", line: 201, detail: "`initial` joga o cartão 420px acima, girado e transparente; `whileInView` o leva ao lugar com uma SPRING de baixa amortização (damping 12) — ele \"quica\" ao pousar — e `delay: i·0,1` escalona a chuva de adesivos." },
  "Carta holográfica": { file: "src/pages/gravity/Gravity.tsx", line: 256, detail: "Duas ideias combinadas. (1) TILT: o ponteiro vira (px,py) em [0,1]; `useSpring` transforma em rotateX/rotateY de ±15° (com o pai em `perspective: 1100px`). (2) FOIL: o mesmo (px,py) vai para as CSS vars `--px/--py`, que movem um `repeating-linear-gradient` arco-íris gigante (`background-size: 260%`) misturado com `mix-blend-mode: color-dodge` sobre a textura escura — o brilho \"troca de cor\" conforme o ângulo, como cartas holográficas. Um brilho especular (`radial-gradient` + `overlay`) segue o ponteiro. Tudo atualiza sem re-render do React (springs + CSS vars)." },
  "Camadas com translateZ": { file: "src/pages/gravity/Gravity.tsx", line: 306, detail: "O contêiner tem `transform-style: preserve-3d` (herdado do motion.div); cada bloco de texto recebe um `translateZ` diferente (30, 80 e 50 px). Ao inclinar a carta, as camadas se deslocam em velocidades distintas — parallax 3D real, só com transform." },
  "Neo-brutalismo com Tailwind": { file: "src/pages/gravity/Playground.tsx", line: 435, detail: "Receita visual: bordas de 3px pretas, SOMBRAS DURAS sem blur (`shadow-[4px_4px_0_#000]`), tipografia pesada (`font-chunk` = Unbounded), cores chapadas e movimento \"mecânico\" (hover sobe e a sombra cresce; active afunda até a sombra sumir). Valores arbitrários `[...]` e variantes `data-[grab=true]:` do Tailwind v4 fazem o resto." },
  "Loops pausados fora da tela": { file: "src/pages/gravity/Playground.tsx", line: 404, detail: "Física + render só rodam enquanto o playground está visível (IntersectionObserver). Rolar a página para longe pausa tudo: CPU a 0% e a simulação continua de onde parou ao voltar." },
  "React Three Fiber (cena declarativa)": { file: "src/pages/orbit/Scene.tsx", line: 13, detail: "R3F expõe o Three.js como componentes React: `<mesh>`, `<group>`, `<instancedMesh>`… são objetos do Three, e `args` são os parâmetros do construtor. `useFrame((state, dt) => …)` é o loop de animação (60×/s) — dentro dele mutamos objetos DIRETAMENTE (rotation, uniforms), sem setState, para não re-renderizar o React." },
  "MeshTransmissionMaterial (vidro)": { file: "src/pages/orbit/Scene.tsx", line: 75, detail: "Material do drei que simula vidro de verdade: renderiza a cena ATRÁS do objeto num buffer (`resolution`, `samples`) e a refrata com `ior` 1,45, `thickness`, `chromaticAberration` (cores separadas nas bordas), `distortion` (ondulação) e `temporalDistortion` (a ondulação evolui no tempo). `backside={false}` poupa uma passada extra. A geometria é um `torusKnotGeometry` de 240×40 segmentos." },
  "Ambiente procedural com Lightformers": { file: "src/pages/orbit/Scene.tsx", line: 222, detail: "`<Environment>` gera um mapa de ambiente (reflexos + luz) a partir dos filhos: cada `Lightformer` é um retângulo/anel/círculo EMISSIVO. Resultado: reflexos nítidos no vidro e nos estilhaços sem baixar nenhum HDRI (.hdr de vários MB) e com cores sob nosso controle. Luz sem baixar nada: Lightformers desenham um \"estúdio\" procedural como mapa de ambiente" },
  "Partículas com ShaderMaterial custom": { file: "src/pages/orbit/Scene.tsx", line: 29, detail: "Um `THREE.Points` com `ShaderMaterial` próprio (shaders em morph.ts). A geometria carrega 4 posições por vértice (`position`, `aP1`, `aP2`, `aP3`) + `aRand`; blending ADITIVO + `depthWrite: false` fazem as partículas somarem luz sem brigar por profundidade. Uniforms mudam por frame (`uMorph`, `uTime`, `uPR` = pixel ratio). A criação fica em useMemo e o cleanup chama `dispose()` (libera a memória da GPU)." },
  "Morph entre 4 formas na GPU": { file: "src/pages/orbit/morph.ts", line: 84, detail: "`uMorph` ∈ [0,3]: a parte inteira (`seg`) escolhe o PAR de formas (0: esfera→toro, 1: toro→cubo, 2: cubo→galáxia) e a fracionária (`f`) é o progresso dentro do par. Cada partícula tem `aRand` ∈ [0,1] que ATRASA o início da própria transição (`smoothstep(aRand·0,42, aRand·0,42 + 0,58, f)`) — por isso o morph vira um enxame fluido e não uma interpolação rígida. No meio do caminho (`mid = sin(t·π)`) a partícula \"respira\" para fora e gira; um ruído senoidal leve mantém tudo vivo. Resultado: 26 mil partículas animadas sem a CPU tocar em nenhuma." },
  "Geração procedural de formas": { file: "src/pages/orbit/morph.ts", line: 10, detail: "Gera 4 \"formas-alvo\" para N partículas (esfera → toro → cubo → galáxia). Isso roda UMA vez na CPU; depois toda a animação (interpolação entre formas) acontece no vertex shader. • esfera: ESPIRAL DE FIBONACCI (ângulo áureo) — distribuição uniforme sem \"polos\" amontoados; raio com ±7% de espessura • toro: parametrização (u, v) com raio do tubo variável • cubo: só a CASCA — escolhe uma das 6 faces e sorteia (a, b) no quadrado • galáxia: 3 braços em espiral logarítmica; `Math.pow(rnd, 0.65)` concentra partículas no centro; espessura decai com o raio Um PRNG determinístico (mulberry32, semente fixa) garante que a cena seja idêntica a cada carregamento." },
  "Câmera guiada pelo scroll": { file: "src/pages/orbit/Scene.tsx", line: 187, detail: "A câmera percorre uma trajetória PARAMÉTRICA em função de p ∈ [0,1]: ângulo `theta = p·1,7π` (quase uma volta e meia), `radius` que encolhe no meio e cresce no fim, e `y` oscilando. Posição = (sin θ·r, y, cos θ·r) e `lookAt` no centro. Zero keyframes: o scroll É a timeline." },
  "Damping independente de FPS": { file: "src/pages/orbit/Scene.tsx", line: 194, detail: "`MathUtils.damp(atual, alvo, lambda, dt)` = lerp exponencial: `atual + (alvo−atual)·(1−e^(−λ·dt))`. Como usa o dt do frame, a sensação é a mesma em 30, 60 ou 144 fps (um lerp fixo de 0,1 por frame seria 4× mais rápido a 144 fps). Mesma função suaviza a escala e o parallax da joia. suaviza o progresso (damping exponencial independente de FPS)" },
  "Estado em refs, não em state": { file: "src/pages/orbit/Orbit.tsx", line: 64, detail: "O progresso do scroll muda ~60×/s. Em `useState` isso re-renderizaria a árvore (e o Canvas) a cada frame. Em `useRef` o valor muda sem render: o `useFrame` do R3F o lê (`progress.current`) quando precisa." },
  "InstancedMesh": { file: "src/pages/orbit/Scene.tsx", line: 140, detail: "Um `InstancedMesh` desenha N cópias da MESMA geometria/material em UMA chamada de desenho (draw call). Cada instância tem sua matriz 4×4: por frame atualizamos posição/rotação/escala num `Object3D` auxiliar (`dummy`), copiamos `dummy.matrix` com `setMatrixAt(i, …)` e avisamos `instanceMatrix.needsUpdate = true`. As \"sementes\" (raio, ângulo, altura, tamanho, velocidade) são determinísticas (números primos) — sem Math.random, o layout é estável." },
  "Pós-processamento": { file: "src/pages/orbit/Scene.tsx", line: 241, detail: "`EffectComposer` (postprocessing) funde os efeitos em UMA passada: Bloom (brilho nas áreas claras, `mipmapBlur` = desfoque barato e suave), ChromaticAberration (franjas de cor), Noise (grão em SOFT_LIGHT) e Vignette (cantos escuros). O MSAA 4× do composer substitui o antialias do canvas (desligado em OrbitCanvas)." },
  "Emissivo > 1 com toneMapped=false": { file: "src/pages/orbit/Scene.tsx", line: 126, detail: "`new THREE.Color(3.2, 1.9, 0.55)` tem canais acima de 1 (HDR). Com `toneMapped={false}` o material não é \"comprimido\" para [0,1], então o `luminanceThreshold` do Bloom (0,22) só pega ESTE objeto e o faz irradiar — o vidro e as partículas não borram junto. núcleo emissivo: cor > 1 + toneMapped=false → o Bloom o faz brilhar" },
  "PerformanceMonitor → DPR adaptativo": { file: "src/pages/orbit/Scene.tsx", line: 256, detail: "`PerformanceMonitor` (drei) mede o FPS ao longo do tempo e chama `onChange({ factor })` com um fator 0–1 (1 = sobra de desempenho). Mapeamos para `dpr = 0,8 + factor` (máx. 1,75): se o PC sofre, a resolução cai e o FPS volta; se sobra, nitidez sobe. `flipflops` limita as oscilações para não ficar alternando sem parar. qualidade adaptativa: PerformanceMonitor mede FPS e ajusta a resolução (dpr)" },
  "eventSource no documento": { file: "src/pages/orbit/Scene.tsx", line: 268, detail: "Por padrão o R3F só recebe ponteiro quando o mouse está sobre o <canvas>; aqui o texto (HTML) fica POR CIMA dele. `eventSource={document.documentElement}` + `eventPrefix=\"client\"` escutam a página inteira, então o parallax do `state.pointer` funciona mesmo com os cartões de texto na frente." },
  "Parallax do ponteiro na joia": { file: "src/pages/orbit/Scene.tsx", line: 94, detail: "`state.pointer` (x,y em [-1,1], fornecido pelo R3F) vira o ALVO de posição da joia (±0,35 / ±0,25) e `damp` o persegue suavemente — a joia \"olha\" para o cursor sem nunca saltar. parallax suave com o ponteiro" },
  "Fog para profundidade": { file: "src/pages/orbit/Scene.tsx", line: 217, detail: "`<fog args={[cor, perto, longe]}>` mistura a cor do fundo com objetos entre 11 e 30 unidades de distância: partículas e estilhaços distantes esmaecem, dando sensação de profundidade e escondendo o \"corte\" da cena." },
  "HUD atualizado direto no DOM": { file: "src/pages/orbit/Orbit.tsx", line: 73, detail: "O HUD (\"scroll 0.512\", \"uMorph 1.54\" e o capítulo ativo) é escrito por `textContent` e `toggleAttribute('data-on')` direto nos nós (via refs) dentro do listener de scroll — sem setState. O CSS estiliza o capítulo ativo por `[data-on]`. `Math.floor(p · nCapítulos)` decide qual capítulo está em foco." },
  "Cards de vidro com blur-in": { file: "src/pages/orbit/Orbit.tsx", line: 130, detail: "`whileInView` anima de `opacity 0 / y 60 / blur(14px)` para nítido quando 45% do cartão entra na tela; o vidro é `backdrop-filter: blur(14px) saturate(1.4)` no CSS (orbit.css `.orbit__card`), borrando o canvas 3D que está atrás do texto." },
  "WebGPU: adapter, device e contexto de canvas": { file: "src/pages/nebula/engine.ts", line: 78, detail: "`navigator.gpu` só existe em navegadores com WebGPU. O adapter representa a GPU física (pode vir null em máquinas sem driver compatível); o device é a conexão lógica que cria recursos." },
  "Compute shader em WGSL (simulação na GPU)": { file: "src/pages/nebula/compute.wgsl", line: 66, detail: "" },
  "Curl noise (fluxo incompressível)": { file: "src/pages/nebula/compute.wgsl", line: 53, detail: "O curl de um campo escalar N é v = (∂N/∂y, −∂N/∂x). Esse campo vetorial tem divergência zero: as partículas escoam como um fluido e não se aglomeram em \"poças\". As derivadas são estimadas por diferenças finitas (e = 0,01)." },
  "Uniform buffer com layout explícito": { file: "src/pages/nebula/compute.wgsl", line: 15, detail: "Regras de alinhamento WGSL: vec2f alinha em 8 bytes, escalares em 4. Este struct tem 12 campos de 4 bytes = 48 bytes (múltiplo de 16, exigido pelo uniform). A ORDEM dos campos aqui precisa bater com engine.ts → writeParams()." },
  "Uniforms escritos por frame com layout explícito": { file: "src/pages/nebula/engine.ts", line: 413, detail: "A ordem dos índices abaixo espelha o struct Params de compute.wgsl (mouse.xy, dt, time, …)." },
  "Storage buffer compartilhado entre compute e render": { file: "src/pages/nebula/engine.ts", line: 209, detail: "UM buffer (STORAGE) é escrito pelo compute shader e lido pelo vertex shader no mesmo frame. A CPU só o preenche uma vez (posições aleatórias); depois a simulação vive na GPU." },
  "Instancing sem vertex buffer": { file: "src/pages/nebula/render.wgsl", line: 33, detail: "Não existe vertex buffer: cada INSTÂNCIA é uma partícula (instance_index lê o storage buffer) e cada VÉRTICE é um canto do quadrado (vertex_index 0..3 num triangle-strip). `draw(4, count)` em engine.ts dispara tudo de uma vez." },
  "Blending aditivo": { file: "src/pages/nebula/engine.ts", line: 153, detail: "Fator \"one + one\": a cor da partícula é SOMADA ao que já está na textura. Onde há muitas partículas sobrepostas a soma passa de 1.0 (por isso a textura é HDR e há tone mapping)." },
  "Rastros por acumulação em textura HDR": { file: "src/pages/nebula/engine.ts", line: 380, detail: "Em vez de limpar a tela, desenhamos um preto translúcido por cima do frame anterior (fade) e SÓ DEPOIS as partículas. O que não é redesenhado esmaece → cauda de cometa." },
  "Tone mapping de Reinhard + vinheta no blit": { file: "src/pages/nebula/blit.wgsl", line: 26, detail: "" },
  "Tamanho e brilho adaptativos à contagem de partículas": { file: "src/pages/nebula/engine.ts", line: 430, detail: "Mais partículas → cada uma menor (size ∝ 1/√n). Abaixo de ~1px o disco \"pisca\" (aliasing), então há um piso de tamanho. Com o piso, a imagem passaria a somar luz demais; por isso medimos a COBERTURA média por pixel (C = n · área_da_partícula / pixels_da_tela) e reduzimos o ganho para que C·ganho fique constante — 60 mil e 2 milhões de partículas têm exposição parecida." },
  "Autopilot do atrator (Lissajous quando ocioso)": { file: "src/pages/nebula/engine.ts", line: 357, detail: "Sem movimento do mouse há 2,5 s, o atrator percorre uma curva de Lissajous — a página continua viva em telas de toque e quando o usuário está lendo." },
  "Validação de shader com getCompilationInfo + fallback": { file: "src/pages/nebula/engine.ts", line: 112, detail: "createShaderModule nunca lança: erros de WGSL aparecem em getCompilationInfo(). Conferimos antes de montar pipelines para dar uma mensagem útil (linha:coluna) e cair no fallback 2D." },
  "Fallback em Canvas 2D com a mesma interface do motor WebGPU": { file: "src/pages/nebula/fallback2d.ts", line: 15, detail: "`createCanvas2DEngine` devolve um objeto `NebulaEngine` idêntico em formato: a UI não sabe (nem precisa saber) qual motor está rodando. Degradação graciosa em vez de tela vazia." },
  "Ciclo de vida seguro (StrictMode, dispose, device.lost)": { file: "src/pages/nebula/engine.ts", line: 329, detail: "`device.lost` resolve quando o device morre; reason === 'destroyed' é o nosso próprio dispose(). Qualquer outro motivo (reset de driver…) avisa a UI para trocar para o fallback." },
  "Shaders importados com ?raw (Vite)": { file: "src/pages/nebula/engine.ts", line: 18, detail: "O sufixo `?raw` faz o Vite entregar o arquivo como string. Assim os shaders são arquivos .wgsl de verdade (com realce no editor) e o MESMO texto alimenta a GPU e o visualizador de código." },
  "Realce de sintaxe WGSL sem biblioteca": { file: "src/pages/nebula/highlight.tsx", line: 6, detail: "Uma única regex com 6 grupos de captura percorre o texto com `matchAll`. O índice do grupo que casou decide a classe CSS (`wgsl-comment`, `wgsl-attr`, …; estilos em nebula.css). O texto entre dois matches é preservado como string pura, então `<pre>` mantém indentação e quebras de linha." },
  "Introspecção da GPU (adapter.info, features, limits)": { file: "src/pages/nebula/Nebula.tsx", line: 304, detail: "" },
  "Intl.NumberFormat em notação compacta": { file: "src/pages/nebula/Nebula.tsx", line: 33, detail: "\"250 mil\", \"1 mi\", \"2 mi\" sem escrever uma linha de formatação manual — respeita o idioma pt-BR." },
  "CSS @scope (estilos isolados sem prefixar tudo)": { file: "src/pages/nebula/nebula.css", line: 4, detail: "Num SPA o CSS de uma página continua carregado nas outras. `@scope (.nebula)` faz TODAS as regras abaixo valerem só dentro de <main class=\"nebula\"> — por isso podemos usar seletores curtos (`h1`, `section`, `button`) sem vazar para as demais páginas, a dock ou o painel de técnicas. Dentro do bloco, `:scope` é o próprio .nebula." },
  "text-box: trim para alinhar o título pela altura das maiúsculas": { file: "src/pages/nebula/nebula.css", line: 55, detail: "`text-box: trim-both cap alphabetic` remove o espaço vazio acima das maiúsculas e abaixo da linha de base, deixando o título alinhado de verdade às margens (Chrome/Edge 133+, Safari 18.2+; onde não existe, apenas sobra um pouco de respiro)." },
  "Dados do mundo em TopoJSON (importado como módulo JSON)": { file: "src/pages/mundi/geo.ts", line: 31, detail: "`world-atlas` publica o Natural Earth já em TopoJSON (arcos compartilhados → ~100 KB para 177 países). O Vite importa .json como módulo ES; `resolveJsonModule` (tsconfig.app.json) dá o tipo." },
  "Renderização de GeoJSON direto no contexto 2D (geoPath com canvas)": { file: "src/pages/mundi/Globe.tsx", line: 66, detail: "`geoPath(projection, context)` não gera string SVG: chama moveTo/lineTo/arc no Canvas. O clipAngle(90) do ortográfico já descarta o hemisfério de trás; linhas (arcos) seguem o círculo máximo." },
  "Terminador dia/noite em tempo real": { file: "src/pages/mundi/geo.ts", line: 171, detail: "Ponto subsolar = onde o Sol está a pino agora. Latitude = declinação solar (aproximação de Cooper: −23,44°·cos(2π/365·(N+10))). Longitude = (12h − hora UTC − equação do tempo) × 15°/h. O hemisfério NOITE é o círculo de raio 90° centrado no ponto ANTI-solar (geoCircle)." },
  "Arrastar com Pointer Events, setPointerCapture e inércia": { file: "src/pages/mundi/Globe.tsx", line: 286, detail: "Pointer Events unificam mouse/toque/caneta. `setPointerCapture` mantém os eventos chegando ao canvas mesmo se o dedo sair dele. A velocidade do último movimento vira `vlon/vlat`, que decai (×0,94/frame)." },
  "Hit-testing de vizinho mais próximo com Delaunay": { file: "src/pages/mundi/Globe.tsx", line: 158, detail: "Em vez de comparar o cursor com TODAS as cidades, `Delaunay.find` navega a triangulação e devolve o ponto mais próximo rapidamente. Reconstruída por frame porque as posições de tela mudam." },
  "Escala de raio por raiz quadrada (área proporcional ao valor)": { file: "src/pages/mundi/Globe.tsx", line: 60, detail: "O olho lê ÁREA, não raio: se o raio fosse linear, Tóquio pareceria 150× maior que Reykjavík. scaleSqrt faz a área do círculo crescer proporcionalmente à população." },
  "Loop de render pausado fora da tela e em aba oculta": { file: "src/pages/mundi/Globe.tsx", line: 270, detail: "" },
  "Morph entre projeções (interpolação de projeções cruas)": { file: "src/pages/mundi/geo.ts", line: 92, detail: "Uma projeção \"crua\" é só uma função (λ, φ) → [x, y]. Misturar duas delas ponto a ponto com `(1−t)·A + t·B` gera uma projeção NOVA e válida para qualquer t em [0,1]; d3.geoProjection() embrulha essa função com escala/translação/rotação. Animando t, o mapa \"derrete\" de uma projeção na outra." },
  "Círculos de Tissot (indicatrizes de deformação)": { file: "src/pages/mundi/geo.ts", line: 59, detail: "`geoCircle().center([lon, lat]).radius(4)` gera um polígono geodésico; ao ser projetado, círculos viram elipses onde há distorção (ângulos) e mudam de tamanho onde há distorção de área." },
  "Mapa coroplético com interpoladores d3-scale-chromatic": { file: "src/pages/mundi/Lab.tsx", line: 23, detail: "Cada indicador vira um valor normalizado u ∈ [0,1] por país (linear ou logarítmico) e a cor é `interpolador(u)`. Normalizamos uma vez aqui (módulo) — redesenhar o mapa só consulta arrays." },
  "Hit-testing com isPointInPath no canvas": { file: "src/pages/mundi/Lab.tsx", line: 186, detail: "Reconstruímos o caminho de cada país com a MESMA transformação do desenho e perguntamos ao canvas `isPointInPath(x, y)`. As coordenadas do ponto são em px de bitmap (não passam pela transformação atual), por isso multiplicamos por dpr. ~176 países por movimento: barato, e exato mesmo com morph/zoom." },
  "Zoom no ponto do cursor (Ctrl + roda / pinça do trackpad)": { file: "src/pages/mundi/Lab.tsx", line: 221, detail: "Só zoom com Ctrl/⌘ pressionado: sem isso a roda continuaria rolando a página (o gesto de pinça do trackpad já chega como wheel com ctrlKey=true). preventDefault exige listener NÃO passivo." },
  "Redesenho sob demanda com rAF agrupado": { file: "src/pages/mundi/Lab.tsx", line: 174, detail: "Em vez de um loop contínuo, `redraw()` agenda UMA pintura por frame (várias mudanças no mesmo frame → 1 pintura). O mapa fica parado (0% de CPU) quando nada acontece." },
  "Legenda interativa que filtra o mapa": { file: "src/pages/mundi/Lab.tsx", line: 388, detail: "O gradiente é um `linear-gradient` montado a partir de 24 amostras do interpolador; passar o mouse pela barra define uma faixa [u0,u1] que o desenho usa para esmaecer os países fora dela." },
  "Relógio local com Intl.DateTimeFormat e fusos IANA": { file: "src/pages/mundi/Mundi.tsx", line: 45, detail: "`timeZone: 'Asia/Tokyo'` etc. — o navegador resolve horário de verão e regras históricas sozinho." },
  "Textura de papel gerada com SVG feTurbulence (data URI)": { file: "src/pages/mundi/mundi.css", line: 21, detail: "Um <svg> inline com `feTurbulence` vira a imagem de fundo: ruído fractal sutil, 0 KB de imagem raster." },
  "Barras de ranking com custom property por linha e animação CSS": { file: "src/pages/mundi/mundi.css", line: 407, detail: "O React só escreve `--w: 63%` em cada linha; largura, grade de fundo e a animação `mundi-grow` (scaleX a partir da esquerda) são puro CSS." },
  "Detecção de recursos (feature detection) em vez de user-agent": { file: "src/pages/nativo/support.ts", line: 34, detail: "Cada teste pergunta diretamente ao navegador se o recurso existe. É a única abordagem que continua correta quando um navegador ganha (ou perde) uma API." },
  "Intl.Segmenter (grafemas e palavras)": { file: "src/pages/nativo/IntlLab.tsx", line: 20, detail: "`string.length` conta unidades UTF-16 — um emoji de família vale 11! O Segmenter segue as regras Unicode (UAX #29): \"grapheme\" = o que o usuário enxerga como UM caractere; \"word\" separa palavras em qualquer idioma (inclusive sem espaços, como japonês)." },
  "Intl.DisplayNames (países, idiomas e moedas traduzidos)": { file: "src/pages/nativo/IntlLab.tsx", line: 66, detail: "Zero tabelas de tradução no bundle: o navegador devolve \"Brasil\", \"ブラジル\", \"البرازيل\"… a partir de códigos ISO." },
  "Intl.RelativeTimeFormat, ListFormat e Collator": { file: "src/pages/nativo/IntlLab.tsx", line: 93, detail: "\"há 3 dias\", \"amanhã\", \"A, B e C\", \"arquivo2 antes de arquivo10\": regras de plural, conjunção e ordenação natural vêm do navegador — nada de `if (n === 1)` espalhado pelo código." },
  "Temporal (datas imutáveis com fuso)": { file: "src/pages/nativo/IntlLab.tsx", line: 133, detail: "Substitui o `Date`: objetos imutáveis, fusos IANA de primeira classe e aritmética sem pegadinhas (`until` já considera horário de verão). Só roda onde `globalThis.Temporal` existe." },
  "Web Crypto: SHA-256 e AES-GCM": { file: "src/pages/nativo/CryptoLab.tsx", line: 48, detail: "`crypto.subtle` só existe em contextos seguros (HTTPS ou localhost). SHA-256 → digest; AES-GCM → generateKey (chave NÃO exportável) + encrypt/decrypt com IV aleatório. Resultado antigo é descartado." },
  "Compression Streams (gzip/deflate nativos)": { file: "src/pages/nativo/CryptoLab.tsx", line: 83, detail: "`Blob.stream().pipeThrough(new CompressionStream('gzip'))` comprime em streaming, sem pako/fflate. Útil para enviar JSON grande ao servidor ou guardar dados no IndexedDB com menos espaço." },
  "URLPattern (roteamento nativo por padrão de URL)": { file: "src/pages/nativo/PatternLab.tsx", line: 22, detail: "`new URLPattern({ pathname })` compila `:nome`, `:n(\\\\d+)` (com regex), `*` e `{grupo}?`. `exec(url)` devolve os grupos nomeados ou null. Erros de sintaxe do padrão lançam — por isso o try/catch e a mensagem na UI." },
  "EyeDropper API (conta-gotas de tela inteira)": { file: "src/pages/nativo/DeviceLab.tsx", line: 22, detail: "`new EyeDropper().open()` mostra uma lupa que lê a cor de QUALQUER pixel da tela (até de outros aplicativos). Rejeita com AbortError se o usuário apertar Esc — por isso o try/catch." },
  "Clipboard API assíncrona": { file: "src/pages/nativo/DeviceLab.tsx", line: 36, detail: "`navigator.clipboard.writeText` devolve uma Promise e pode ser negada (sem foco/permissão)." },
  "Eleição de líder entre abas com Web Locks": { file: "src/pages/nativo/TabsLab.tsx", line: 35, detail: "`navigator.locks.request(nome, callback)` só executa o callback quando ESTA aba obtém o lock; ele permanece seguro enquanto a promessa devolvida não resolver. Resolvemos a promessa no cleanup. `AbortController` cancela o pedido se ainda estivermos na fila (ex.: StrictMode desmontando)." },
  "Presença e mensagens entre abas com BroadcastChannel": { file: "src/pages/nativo/TabsLab.tsx", line: 58, detail: "Canal nomeado: tudo que uma aba `postMessage` chega às DEMAIS (não a si mesma). Mensagens são clonadas com structured clone, então aceitam objetos simples. O heartbeat de 2 s + expiração de 6 s dá presença confiável mesmo se uma aba travar ou for fechada de forma abrupta." },
  "scheduler.yield() para fatiar tarefas longas": { file: "src/pages/nativo/SchedulerLab.tsx", line: 28, detail: "Cede a thread ao navegador entre fatias. Prefere `scheduler.yield()` (retoma com prioridade, na frente de outras tarefas pendentes); se não existir, cai em `setTimeout(0)`, que funciona mas retoma no fim da fila." },
  "Screen Wake Lock (impede a tela de apagar)": { file: "src/pages/nativo/DeviceLab.tsx", line: 74, detail: "O navegador SOLTA o lock sozinho quando a aba fica oculta; o evento `release` mantém o estado da UI sincronizado. Útil em receitas, apresentações, mapas e players." },
  "OPFS — sistema de arquivos privado de origem": { file: "src/pages/nativo/DeviceLab.tsx", line: 166, detail: "`navigator.storage.getDirectory()` devolve uma pasta INVISÍVEL ao usuário, só desta origem, com API de arquivos real (handles, streams graváveis). Mais rápido que IndexedDB para blobs e sem diálogos de permissão. Aqui lemos a nota salva (se existir) ao montar." },
  "PerformanceObserver (Core Web Vitals ao vivo)": { file: "src/pages/nativo/VitalsLab.tsx", line: 36, detail: "Um observador por tipo de entrada: `largest-contentful-paint` (LCP), `layout-shift` (CLS: soma dos deslocamentos SEM interação recente), `longtask` (>50 ms na thread principal) e `event` (latência de interação, base do INP). `buffered: true` entrega também o que aconteceu ANTES de assinarmos. Acumulamos em variáveis locais do efeito e gravamos valores absolutos — assim o StrictMode (que monta o efeito duas vezes) não soma as entradas em dobro." },
  "matchMedia reativo com useSyncExternalStore": { file: "src/lib/hooks.ts", line: 16, detail: "`subscribe` registra o listener `change` da MediaQueryList; `getSnapshot` lê `matches`; o 3º argumento é o valor no servidor. O React re-renderiza só quando o resultado muda — sem estado duplicado nem efeitos." },
  "ResizeObserver (reage ao tamanho do ELEMENTO, não da janela)": { file: "src/pages/nativo/VitalsLab.tsx", line: 139, detail: "`contentBoxSize` entrega medidas fracionárias sem forçar layout (ao contrário de ler getBoundingClientRect em loop). Base de container queries em JS, gráficos responsivos e virtualização." },
  "CSS subgrid (linhas compartilhadas entre cartões)": { file: "src/pages/nativo/nativo.css", line: 181, detail: "O cartão ocupa 4 linhas da grade-pai (cabeçalho, título, api, corpo) e herda os tamanhos delas com `grid-template-rows: subgrid`. Cartões vizinhos ficam com título, selo e corpo ALINHADOS mesmo com conteúdos de alturas diferentes — algo que flexbox/grid simples não faz." },
  "field-sizing: content e :has() em formulários": { file: "src/pages/nativo/nativo.css", line: 263, detail: "`field-sizing: content` faz o textarea crescer com o texto (sem JS de auto-resize) e o `:has(:focus-visible)` do .nat-spec destaca o cartão inteiro quando QUALQUER campo dentro dele recebe foco pelo teclado." },
  "Web Component (Custom Element + Shadow DOM)": { file: "src/pages/terminal/crt-element.ts", line: 104, detail: "Classe que estende HTMLElement + `customElements.define`. O Shadow DOM isola o CSS interno (nada vaza para a página nem o contrário) e `observedAttributes` + `attributeChangedCallback` fazem do atributo `power` a API pública do componente." },
  "Constructable Stylesheets (adoptedStyleSheets)": { file: "src/pages/terminal/crt-element.ts", line: 16, detail: "`new CSSStyleSheet()` + `replaceSync()` cria uma folha fora do DOM; cada shadow root a \"adota\". Vantagem sobre <style> em cada instância: parse uma vez só e memória compartilhada." },
  "Efeito CRT em CSS (scanlines, vinheta, flicker, power-on)": { file: "src/pages/terminal/crt-element.ts", line: 69, detail: "Camadas absolutas sobrepostas ao conteúdo: .scan (repeating-linear-gradient + multiply), .roll (barra de varredura animada), .vig (vinheta radial), .glare (reflexo no vidro); o flicker oscila a opacidade; o power-on é uma transição de scaleY no :host([power])." },
  "Custom Element no React 19 (atributos e slot)": { file: "src/pages/terminal/Terminal.tsx", line: 230, detail: "O React 19 reconhece elementos customizados: strings viram atributos, funções/objetos viram propriedades. O conteúdo filho vai para o <slot> do Shadow DOM." },
  "::part() + custom properties atravessando o Shadow DOM": { file: "src/pages/terminal/terminal.css", line: 21, detail: "O elemento expõe `part=\"screen|glass|bezel\"`; aqui a PÁGINA (fora do shadow) dimensiona o componente sem conhecer o CSS interno. Já `--crt-tint` entra no shadow porque custom properties herdam através dele." },
  "Brilho de fósforo e aberração cromática só com text-shadow": { file: "src/pages/terminal/terminal.css", line: 47, detail: "Três sombras sobrepostas: (1) halo na cor do fósforo; (2) fantasma vermelho 1px à direita; (3) fantasma ciano 1px à esquerda. É a \"falha de convergência\" dos tubos CRT, sem JavaScript." },
  "Registro extensível de comandos (objeto nome → { help, run })": { file: "src/pages/terminal/commands.ts", line: 93, detail: "O `help` e o autocompletar percorrem este mesmo objeto: adicionar uma chave cria o comando, a ajuda e a sugestão de Tab de uma vez." },
  "Parser de linha de comando com aspas (regex + matchAll)": { file: "src/pages/terminal/commands.ts", line: 266, detail: "" },
  "Autocompletar por Tab com prefixo comum": { file: "src/pages/terminal/commands.ts", line: 290, detail: "" },
  "Histórico de comandos com ↑/↓, Tab e Ctrl+L": { file: "src/pages/terminal/Terminal.tsx", line: 190, detail: "`histIdx` aponta para o item do histórico em exibição (−1 = linha em edição, guardada em `draft`). Tab usa `complete()` (prefixo comum + lista de opções); Ctrl+L limpa; Ctrl+C descarta a linha." },
  "Sequência de boot assíncrona e cancelável": { file: "src/pages/terminal/Terminal.tsx", line: 103, detail: "Cada linha entra num setTimeout encadeado. Qualquer tecla (ou reduced-motion) \"pula\" a animação e despeja o resto de uma vez. O cleanup cancela os timers — e como o StrictMode monta duas vezes em dev, o efeito começa com `clear` para não duplicar linhas." },
  "Navegação programática com View Transition": { file: "src/pages/terminal/Terminal.tsx", line: 158, detail: "`navigate(path, { viewTransition: true })` — o mesmo círculo de revelação do dock, disparado por texto." },
  "package.json importado como módulo (comando stack)": { file: "src/pages/terminal/commands.ts", line: 181, detail: "`resolveJsonModule` deixa importar o JSON como objeto tipado: a lista de bibliotecas e versões exibida no terminal é sempre a real, sem duplicar nada à mão." },
  "Detecção de hardware do navegador (neofetch)": { file: "src/pages/terminal/commands.ts", line: 68, detail: "Combina `navigator.hardwareConcurrency/deviceMemory/userAgentData`, `screen`, `matchMedia`, `Intl...resolvedOptions().timeZone` e a extensão de debug do WebGL — tudo com fallback." },
  "Toro 3D em ASCII (z-buffer + iluminação)": { file: "src/pages/terminal/donut.ts", line: 22, detail: "Pontos do toro → rotação (A em X, B em Z) → perspectiva → z-buffer por célula → rampa de caracteres." },
  "Chuva de caracteres em canvas com rastro por fade": { file: "src/pages/terminal/matrix.ts", line: 14, detail: "" },
  "Saída de terminal acessível (role log)": { file: "src/pages/terminal/Terminal.tsx", line: 238, detail: "`role=\"log\"` já implica aria-live=\"polite\": leitores de tela anunciam só o que for ACRESCENTADO." },
  "Atalhos clicáveis (chips) para telas de toque": { file: "src/pages/terminal/Terminal.tsx", line: 288, detail: "Sem teclado físico o terminal seria inútil; os chips executam o comando com um toque e ensinam a sintaxe. A lista vem do array CHIPS." },
  "Code-splitting por rota": { file: "src/router.tsx", line: 15, detail: "Cada página (e suas libs pesadas — Three, Matter, GSAP) vira um chunk baixado só quando necessário. `lazy` do React Router carrega o módulo ANTES de navegar, então a View Transition acontece sem flash de \"carregando\". O `import()` dinâmico é o que faz o Vite/Rolldown gerar um arquivo separado por rota." },
  "View Transitions API entre páginas": { file: "src/index.css", line: 78, detail: "Como funciona: `<Link viewTransition>` (React Router) chama `document.startViewTransition()` ao navegar. O navegador tira um \"print\" da página velha (`::view-transition-old(root)`) e monta a nova ao vivo (`::view-transition-new(root)`); aqui animamos a NOVA com um `clip-path: circle()` que cresce de 0% a 150% a partir de (--vt-x, --vt-y). Essas duas variáveis são gravadas em `Dock.tsx → setTransitionOrigin` no instante do clique, então o círculo nasce exatamente embaixo do dedo/mouse. A página velha encolhe e escurece (`vt-old`). Sem JavaScript de animação: só CSS." },
  "view-transition-name para elementos persistentes": { file: "src/index.css", line: 117, detail: "Dar `view-transition-name` a um elemento o tira do snapshot \"root\": ele ganha seu próprio par old/new. Como dock e botão de técnicas existem nas DUAS páginas, anulamos a animação (duration 0) e escondemos o \"old\" — o resultado é que eles ficam parados enquanto o resto se revela em círculo." },
  "Dock com magnificação (estilo macOS)": { file: "src/shell/Dock.tsx", line: 44, detail: "Pipeline de MotionValues (nenhum re-render do React por movimento do mouse): mouseX (px) → distance (cursor − centro do item) → rawSize (46→78→46 por interpolação linear) → size (useSpring: mola dá o \"gelatinoso\") → width/height do tile. O indicador do item ativo usa `layoutId=\"dock-active\"`: o Motion anima o MESMO elemento de um item para outro (shared layout animation) em vez de desmontar/montar. Distância (px) do cursor ao centro deste item → tamanho (efeito \"dock do macOS\")" },
  "Container query units (cqw)": { file: "src/shell/dock.css", line: 34, detail: "O tile (que muda de 46px a 78px pela magnificação, ver Dock.tsx) é um `container-type: inline-size`; o glifo usa `font-size: 42cqw` = 42% da LARGURA DO TILE. Resultado: o ícone cresce junto com o tile sem nenhuma linha de JavaScript e sem media query." },
  "Cursor customizado com inércia": { file: "src/shell/Cursor.tsx", line: 8, detail: "Dois elementos fixos: o PONTO segue o ponteiro na hora; o ANEL persegue com interpolação linear (`rx += (x − rx) · 0,16` a cada frame), o que dá a sensação de \"peso\". - o anel cresce sobre links/botões/inputs (`closest('a, button, …')` → `data-hot`) - `mix-blend-mode: difference` (cursor.css) inverte a cor do que está atrás → legível em qualquer fundo - só ativa com `(pointer: fine)`: em telas de toque nem é criado - posição escrita direto em `style.transform` por rAF: ZERO re-render do React por movimento - estados (visível, sobre-algo, pressionado) viajam como `data-*` e o CSS reage a eles" },
  "Dialog nativo com animação de entrada/saída em CSS": { file: "src/shell/techpanel.css", line: 42, detail: "`<dialog>.showModal()` já entrega top layer, foco preso, Esc e ::backdrop. O problema clássico é animar a SAÍDA: o navegador troca `display` para `none` na hora. A solução moderna: `transition-behavior: allow-discrete` (aqui na forma curta `display .5s allow-discrete, overlay .5s allow-discrete`) mantém o elemento visível durante a transição, e `@starting-style` define o estado inicial da ENTRADA. Estado fechado = `translate: 100% 0; opacity: 0`." },
  "Tailwind CSS v4 (CSS-first)": { file: "src/index.css", line: 14, detail: "Não existe tailwind.config.js: `@import 'tailwindcss'` + `@theme { … }` declaram os tokens aqui mesmo (cada `--color-*` vira utilitários `bg-*`, `text-*`; `--font-*` vira `font-*`) e o plugin `@tailwindcss/vite` (vite.config.ts) faz o resto. O Tailwind varre o código-fonte sozinho atrás de classes." },
  "Scroll suave com Lenis + ticker do GSAP": { file: "src/lib/useSmoothScroll.ts", line: 25, detail: "- Lenis interpola o scroll (`lerp: 0.09`) e \"rouba\" a roda do mouse; precisamos avisar o ScrollTrigger a cada passo (`lenis.on('scroll', ScrollTrigger.update)`) senão as animações atrasam - UM único requestAnimationFrame para tudo: `gsap.ticker.add(t => lenis.raf(t * 1000))` — Lenis, ScrollTrigger e tweens do GSAP avançam no MESMO tick (sem brigar por frames) - `lagSmoothing(0)` desliga a compensação de lag do GSAP, que causaria saltos com scroll interpolado - respeita `prefers-reduced-motion` (não cria o Lenis) e devolve cleanup completo Uso: chame `useSmoothScroll()` no componente da página que deve ter scroll suave." },
  "Guia visual de técnicas (spotlight)": { file: "src/shell/Spotlight.tsx", line: 11, detail: "O contorno segue a borda REAL do elemento `[data-spot]` (recortada à área visível). Cantos brancos + uma etiqueta colada na borda dizem o que é aquele bloco. O escurecimento fica SÓ fora do bloco, para o olho ir direto nele — e o miolo continua interativo (dá para mexer o mouse e ver a técnica funcionando). O cartão é a aula, em três partes: onde na página, como foi utilizada, onde no código. Blocos que ocupam a tela (shader, WebGPU, página inteira) não ganham um retângulo flutuante no meio: o contorno vai até a borda deles e o véu fica mais claro." },
}
